#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Regular_triangulation_3.h>
#include <CGAL/Cartesian_d.h>
#include <CGAL/Kernel_d/Hyperplane_d.h>
#include <vector>

using K = CGAL::Exact_predicates_inexact_constructions_kernel;
using RT = CGAL::Regular_triangulation_3<K>;
using Vector = K::Vector_3;
using Weighted_point = RT::Weighted_point;
using Bare_point = RT::Bare_point;

typedef CGAL::Cartesian_d<double> LiftedK;
typedef CGAL::Point_d<LiftedK> LiftedPoint;
typedef CGAL::Hyperplane_d<LiftedK> HyperPlane;

Vector calculate_velocity(RT const &rt, RT::Cell_handle c, double time) {
    std::vector<LiftedPoint> lifted_points;
    for (int i = 0; i < 4; ++i) {
        Weighted_point wp = c->vertex(i)->point();
        Bare_point bp = wp.point();
        double w = wp.weight();
        lifted_points.push_back(LiftedPoint(4, { bp.x(), bp.y(), bp.z(), w + time }));
    }

    HyperPlane hyperplane(
        lifted_points[0], 
        lifted_points[1], 
        lifted_points[2], 
        lifted_points[3]
    );

    auto normal = hyperplane.orthogonal_vector();
    return Vector(normal[0], normal[1], normal[2]);
}

